<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>{{ $event->exists?'ویرایش رویداد':'رویداد جدید' }}</title><link rel="stylesheet" href="/css/cinema.css"></head><body class="admin-body"><main class="admin-main" style="margin:0"><section class="admin-card"><h1>{{ $event->exists?'ویرایش رویداد':'ثبت رویداد جدید' }}</h1><form method="post" enctype="multipart/form-data" action="{{ $event->exists?route('admin.events.update',$event):route('admin.events.store') }}">@csrf @if($event->exists) @method('PUT') @endif<label>عنوان<input class="input" name="title" value="{{ $event->title }}" required></label><label>خلاصه<textarea class="input" name="summary">{{ $event->summary }}</textarea></label><label>توضیحات<textarea class="input" rows="5" name="description">{{ $event->description }}</textarea></label><label>نوع<select class="input" name="type"><option value="cinema" @selected($event->type==='cinema')>سینما</option><option value="theater" @selected($event->type==='theater')>تئاتر</option><option value="concert" @selected($event->type==='concert')>کنسرت</option></select></label><label>دسته‌بندی<select class="input" name="category_id"><option value="">بدون دسته‌بندی</option>@foreach($categories as $category)<option value="{{ $category->id }}" @selected($event->category_id===$category->id)>{{ $category->name }}</option>@endforeach</select></label><label>مدت<input class="input" type="number" name="duration" value="{{ $event->duration?:105 }}"></label><label>وضعیت<select class="input" name="status"><option value="published" @selected($event->status==='published')>منتشرشده</option><option value="draft" @selected($event->status==='draft')>پیش‌نویس</option><option value="archived" @selected($event->status==='archived')>بایگانی</option></select></label><label>پوستر<input class="input" type="file" name="poster" accept="image/*"></label><label>گالری<input class="input" type="file" name="gallery[]" accept="image/*" multiple></label><label>تریلر<input class="input